import {importEst} from './est.js';
import {planPriceUpdate,validatePriceReference} from './price-update.js';
import {resourceLibrary} from './resource-pricing.js';

export function setupPriceUpdate(api){
 const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>Number(n).toLocaleString('ko-KR');
 const button=document.createElement('button');button.id='priceUpdateBtn';button.className='button';button.textContent='단가 업데이트';document.querySelector('#estToolsDialog .tool-menu').append(button);
 document.body.insertAdjacentHTML('beforeend',`<dialog id="priceUpdateDialog" class="auto-link-dialog price-update-dialog"><div class="dialog-head"><div><h2>단가 업데이트</h2><p>최신 DB로 노임·자재·연료·장비 가격을 갱신합니다. 못 찾은 품목은 기존 단가를 유지합니다.</p></div><button class="icon-btn" id="priceUpdateClose" aria-label="닫기">×</button></div><div class="auto-link-controls"><label>최신 기준 DB <select id="priceUpdateReference"></select></label><button class="button" id="priceUpdateUpload">최신 DB 파일 선택</button><input id="priceUpdateFile" type="file" accept=".estx,.ebkx" hidden></div><fieldset class="price-update-targets"><legend>업데이트할 등록 DB</legend><div id="priceUpdateTargets"></div><p>현재 열어둔 내역도 함께 업데이트합니다. 산식·투입량·계수는 유지됩니다.</p></fieldset><div class="auto-link-controls"><button class="button primary" id="priceUpdatePreview">변경 내역 확인</button><strong id="priceUpdateStatus" role="status"></strong><label>표시 <select id="priceUpdateFilter"><option value="all">전체</option><option value="changed">금액 변경</option><option value="retained">기존 단가 유지</option><option value="unverified">산식 검증 필요</option></select></label></div><p class="auto-priority-note" id="priceUpdateTotals">등록 DB와 현재 내역의 변경값을 확인한 뒤 적용하세요. 보관함의 다른 공사는 변경하지 않습니다.</p><div class="auto-link-results"><table><thead><tr><th>자료 / 품목</th><th>이전 단가</th><th>업데이트 후</th><th>결과 / 기존 단가 유지 사유</th></tr></thead><tbody id="priceUpdateRows"></tbody></table></div><div class="auto-link-controls"><button class="button small" id="priceUpdatePrev">이전</button><span id="priceUpdatePage"></span><button class="button small" id="priceUpdateNext">다음</button></div><div class="dialog-actions"><button class="button" id="priceUpdateRestore">직전 업데이트 되돌리기</button><button class="button" id="priceUpdateCancel">닫기</button><button class="button primary" id="priceUpdateApply" disabled>백업하고 업데이트 적용</button></div></dialog>`);
 let incoming=null,plan=null,baseLibraries,signature='',page=0,running=false,hasBackup=false;
 const available=()=>[...api.getLibraries().filter(l=>l.name!==incoming?.name),...(incoming?[incoming]:[])];
 const reference=()=>available().find(l=>l.id===$('priceUpdateReference').value);
 function clear(){plan=null;page=0;$('priceUpdateApply').disabled=true;$('priceUpdateStatus').textContent='';$('priceUpdateRows').innerHTML='';$('priceUpdatePage').textContent='';$('priceUpdateTotals').textContent='변경 내역을 확인한 뒤 적용하세요.';}
 function targets(){const ref=reference();$('priceUpdateTargets').innerHTML=api.getLibraries().filter(l=>l.name!==ref?.name).map(l=>`<label><input type="checkbox" data-price-target="${esc(l.id)}" ${!l.priceUpdateReference&&!/\d{4}-\d{2}-main\.estx$/i.test(l.name)?'checked':''}> ${esc(l.name)}</label>`).join('')||'<p>등록된 추가 DB가 없습니다. 현재 내역만 업데이트합니다.</p>';clear();}
 function references(selected){$('priceUpdateReference').innerHTML=available().map(l=>`<option value="${esc(l.id)}">${esc(l.name)}</option>`).join('');if(selected)$('priceUpdateReference').value=selected;targets();}
 function guard(){if(api.getLibraries()!==baseLibraries||JSON.stringify(api.getProject())!==signature)throw Error('내역 또는 DB가 변경되었습니다. 변경 내역을 다시 확인하세요.');}
 function busy(value){running=value;for(const id of ['priceUpdateUpload','priceUpdateReference','priceUpdatePreview','priceUpdateClose','priceUpdateCancel','priceUpdateRestore'])$(id).disabled=value;document.querySelectorAll('[data-price-target]').forEach(b=>b.disabled=value);$('priceUpdateApply').disabled=value||!plan;$('priceUpdateRestore').disabled=value||!hasBackup;}
 function render(){
  if(!plan)return;const filter=$('priceUpdateFilter').value,rows=plan.rows.filter(r=>filter==='changed'?r.changed:filter==='retained'?r.warnings.some(w=>w.retained!==false):filter==='unverified'?r.ready===false:true),pages=Math.max(1,Math.ceil(rows.length/100));page=Math.min(page,pages-1);
  $('priceUpdateRows').innerHTML=rows.slice(page*100,page*100+100).map(r=>`<tr><td><small>${esc(r.scope)}</small><br><strong>${esc(r.name)}</strong><br>${esc(r.spec)}</td><td class="number">${money(r.before)}</td><td class="number">${r.ready===false?'<strong class="error-text">미확정</strong>':money(r.after)}</td><td>${r.changed?'금액 변경':'금액 동일'}${r.warnings.length?'<details open><summary>'+(r.ready===false?'산식 검증 필요':'기존 단가 유지')+' '+r.warnings.length+'건</summary>'+r.warnings.map(w=>`<p>${esc(w.resource?.name||r.name)} ${esc(w.resource?.spec||'')} · ${esc(w.reason)}</p>`).join('')+'</details>':''}${r.changes.length?'<details><summary>가격 적용 근거 '+r.changes.length+'건</summary>'+r.changes.map(c=>`<p>${esc(c.name)} ${esc(c.spec)} · ${money(c.before)} → ${money(c.after)}${esc(c.currency||'원')} · ${esc(c.source)}</p>`).join('')+'</details>':''}</td></tr>`).join('')||'<tr><td colspan="4">해당 항목이 없습니다.</td></tr>';
  $('priceUpdatePage').textContent=`${page+1} / ${pages} · ${rows.length}행`;$('priceUpdatePrev').disabled=page===0;$('priceUpdateNext').disabled=page===pages-1;
 }
 button.onclick=async()=>{incoming=null;plan=null;references(resourceLibrary(api.getProject(),api.getLibraries())?.id);$('priceUpdateDialog').showModal();try{hasBackup=!!(await api.storage.get('priceUpdateBackup'));$('priceUpdateRestore').disabled=!hasBackup;}catch(e){api.toast(e.message);}};
 $('priceUpdateReference').onchange=targets;$('priceUpdateTargets').onchange=clear;$('priceUpdateUpload').onclick=()=>$('priceUpdateFile').click();
 $('priceUpdateFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;clear();busy(true);try{if(f.size>80*1024*1024)throw Error('DB 파일은 80MB 이하만 지원합니다.');$('priceUpdateStatus').textContent='최신 DB를 읽고 있습니다…';const next=await importEst(await f.arrayBuffer(),f.name);validatePriceReference(next);incoming=next;references(next.id);$('priceUpdateStatus').textContent='파일 준비 완료 · 변경 내역 확인을 누르세요.';}catch(e){api.toast(e.message);$('priceUpdateStatus').textContent=e.message;}finally{busy(false);}};
 $('priceUpdatePreview').onclick=async()=>{busy(true);plan=null;$('priceUpdateStatus').textContent='단가를 대조하고 있습니다…';try{await new Promise(r=>setTimeout(r,0));const ref=reference();if(!ref)throw Error('최신 DB 파일을 선택하세요.');baseLibraries=api.getLibraries();const baseProject=structuredClone(api.getProject());signature=JSON.stringify(baseProject);const ids=[...document.querySelectorAll('[data-price-target]:checked')].map(b=>b.dataset.priceTarget);plan=planPriceUpdate(baseProject,baseLibraries,ref,ids);page=0;render();$('priceUpdateStatus').textContent=`변경 ${plan.summary.changed}행 · 동일 ${plan.summary.unchanged}행 · 기존 단가 유지 ${plan.summary.retained}건 · 산식 미확정 ${plan.summary.unverified}행`;$('priceUpdateTotals').textContent=`현재 내역 도급액 ${money(plan.before.contract)} → ${money(plan.after.contract)}원 / 총공사비 ${money(plan.before.grand)} → ${money(plan.after.grand)}원. 기준 DB에 없는 품목은 기존 단가로 포함합니다. ${plan.after.missing?'미확정 '+plan.after.missing+'행이 합계에서 빠져 있어 지급액으로 사용할 수 없습니다.':'현재 내역의 미확정 행은 없습니다.'}`;}catch(e){plan=null;$('priceUpdateStatus').textContent=e.message;api.toast(e.message);}finally{busy(false);}};
 $('priceUpdateApply').onclick=async()=>{if(!plan)return;busy(true);try{guard();$('priceUpdateStatus').textContent='DB와 내역을 저장하고 있습니다…';await api.apply(plan);hasBackup=true;$('priceUpdateDialog').close();api.toast(`단가 업데이트 완료 · 변경 ${plan.summary.changed}행 / 기존 단가 유지 ${plan.summary.retained}건 / 산식 미확정 ${plan.summary.unverified}행`);}catch(e){api.toast(e.message);}finally{busy(false);}};
 $('priceUpdateRestore').onclick=async()=>{if(!confirm('직전 단가 업데이트 전의 DB와 내역으로 되돌립니다. 업데이트 이후 내역 편집도 되돌아갑니다. 계속할까요?'))return;busy(true);try{$('priceUpdateStatus').textContent='이전 자료로 복원하고 있습니다…';await api.restore();hasBackup=false;$('priceUpdateDialog').close();api.toast('단가 업데이트 전 자료로 되돌렸습니다.');}catch(e){api.toast(e.message);}finally{busy(false);}};
 $('priceUpdateClose').onclick=$('priceUpdateCancel').onclick=()=>{if(!running)$('priceUpdateDialog').close();};$('priceUpdateDialog').addEventListener('cancel',e=>{if(running)e.preventDefault();});$('priceUpdateFilter').onchange=()=>{page=0;render();};$('priceUpdatePrev').onclick=()=>{page--;render();};$('priceUpdateNext').onclick=()=>{page++;render();};
 return {open:()=>button.click()};
}
